    internal static void Emit(StringBuilder b,ValueIrNativeStorage call)
    {
        var binding=Bindings[call.Operation];
        if(binding.Types.Length!=call.Arguments.Count)throw new NotSupportedException("Raw GX argument mismatch.");
        var args=call.Arguments.Select((a,i)=>"("+(binding.Types[i] switch {'f'=>"float",'p' or 'h'=>"uint64_t",'c'=>"uint32_t",_=>"int32_t"})+")v"+a.Id);
        var expression=binding.Symbol+"("+string.Join(", ",args)+")";
        if(call.Result is {} result)b.AppendLine("  v"+result.Id+" = "+expression+";");
        else b.AppendLine("  "+expression+";");
    }
